var cam=UnityEngine.Camera.main.GetComponent<CameraFollow>();var p=UnityEngine.Object.FindFirstObjectByType<PlayerCombat>();var text=new System.Text.StringBuilder();text.AppendLine("open="+SettingsMenu.IsOpen+" scale="+UnityEngine.Time.timeScale+" BGM="+GameSettings.Bgm+" FX="+GameSettings.Effects+" voice="+GameSettings.Voice+" sensitivity="+cam.sensitivity+" firstPerson="+cam.firstPerson+" vibration="+Rumble.Enabled);foreach(var channel in UnityEngine.Object.FindObjectsByType<AudioVolumeChannel>(UnityEngine.FindObjectsSortMode.None))text.AppendLine(channel.bus+" sourceVolume="+channel.source.volume);text.AppendLine("modelVisible="+System.Linq.Enumerable.All(p.GetComponentsInChildren<UnityEngine.Renderer>(),r=>r.shadowCastingMode!=UnityEngine.Rendering.ShadowCastingMode.ShadowsOnly));return text.ToString();
